-- 001: extensions, schemas and shared helper functions
--
-- Naming conventions (project-wide):
--   * lowercase snake_case identifiers
--   * UUID primary keys generated by gen_random_uuid()
--   * monetary columns are NUMERIC(18,4); timestamps are TIMESTAMPTZ
--   * every tenant-scoped table carries tenant_id and UNIQUE (tenant_id, id) so
--     children can use composite foreign keys that make cross-tenant references
--     structurally impossible
--   * no ON DELETE CASCADE between business aggregates: posted documents are
--     retained, and lifecycle is expressed with status columns

CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS btree_gist;

CREATE SCHEMA IF NOT EXISTS platform;
CREATE SCHEMA IF NOT EXISTS identity;
CREATE SCHEMA IF NOT EXISTS access;
CREATE SCHEMA IF NOT EXISTS licensing;
CREATE SCHEMA IF NOT EXISTS hotel;
CREATE SCHEMA IF NOT EXISTS housekeeping;
CREATE SCHEMA IF NOT EXISTS maintenance;
CREATE SCHEMA IF NOT EXISTS restaurant;
CREATE SCHEMA IF NOT EXISTS bar;
CREATE SCHEMA IF NOT EXISTS inventory;
CREATE SCHEMA IF NOT EXISTS procurement;
CREATE SCHEMA IF NOT EXISTS finance;
CREATE SCHEMA IF NOT EXISTS payments;
CREATE SCHEMA IF NOT EXISTS workforce;
CREATE SCHEMA IF NOT EXISTS integration;
CREATE SCHEMA IF NOT EXISTS notification;
CREATE SCHEMA IF NOT EXISTS audit;
CREATE SCHEMA IF NOT EXISTS reporting;
CREATE SCHEMA IF NOT EXISTS mobile;

-- Tenant context used by row level security policies.
-- The API sets it per transaction with SET LOCAL app.tenant_id = '<uuid>'.
CREATE OR REPLACE FUNCTION app_current_tenant_id() RETURNS uuid
LANGUAGE sql STABLE AS $$
  SELECT nullif(current_setting('app.tenant_id', true), '')::uuid
$$;

-- Standard updated_at maintenance.
CREATE OR REPLACE FUNCTION app_touch_updated_at() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;

-- Reject all mutations: attached to append-only ledgers.
CREATE OR REPLACE FUNCTION app_reject_mutation() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION
    'Table %.% is append-only; create a reversal or adjustment record instead of %',
    TG_TABLE_SCHEMA, TG_TABLE_NAME, TG_OP
    USING ERRCODE = 'restrict_violation';
END;
$$;

-- Human readable document numbers, race-free per tenant and counter key.
CREATE OR REPLACE FUNCTION app_next_document_number(
  p_tenant_id uuid,
  p_counter_key text,
  p_prefix text DEFAULT ''
) RETURNS text
LANGUAGE plpgsql AS $$
DECLARE
  v_value bigint;
BEGIN
  INSERT INTO platform.doc_counters (tenant_id, counter_key, next_value)
  VALUES (p_tenant_id, p_counter_key, 1)
  ON CONFLICT (tenant_id, counter_key)
  DO UPDATE SET next_value = platform.doc_counters.next_value + 1
  RETURNING next_value INTO v_value;
  RETURN p_prefix || to_char(v_value, 'FM000000');
END;
$$;
